import { describe, expect, it } from "vitest";
import { createGeospatialCamera, setGeospatialOrientation } from "@babylonjs/lite";
import { tiltGlobeCamera } from "./globe-tilt";

const R = 6371000;
function dirOf(cam: any) { return cam._lookAt as { x: number; y: number; z: number }; }
function tiltFromLook(cam: any) {
    const c = cam.center; const m = Math.hypot(c.x, c.y, c.z);
    const up = { x: c.x / m, y: c.y / m, z: c.z / m };
    const l = dirOf(cam);
    return Math.acos(Math.max(-1, Math.min(1, -(l.x * up.x + l.y * up.y + l.z * up.z))));
}

describe("tiltGlobeCamera", () => {
    it("tilts a fresh (fully zoomed out) camera and keeps zoom, heading, centre", () => {
        const cam = createGeospatialCamera({ planetRadius: R });
        setGeospatialOrientation(cam, { yaw: 0.7 });
        const r0 = cam.radius, y0 = cam.yaw, c0 = { ...cam.center };
        tiltGlobeCamera(cam, 1.0);
        expect(cam.pitch).toBeCloseTo(1.0, 9);
        expect(tiltFromLook(cam)).toBeCloseTo(1.0, 6);
        expect(cam.radius).toBe(r0);
        expect(cam.yaw).toBeCloseTo(y0, 9);
        expect(cam.center).toEqual(c0);
        // eye is centre - look*radius, so look-at point is the centre
        const p = cam.position, l = dirOf(cam);
        expect(p.x + l.x * cam.radius).toBeCloseTo(c0.x, 0);
        expect(p.y + l.y * cam.radius).toBeCloseTo(c0.y, 0);
        expect(p.z + l.z * cam.radius).toBeCloseTo(c0.z, 0);
    });
    it("holds the tilt across zoom changes", () => {
        for (const p of [0.1, 0.6, 1.2]) {
            const cam = createGeospatialCamera({ planetRadius: R });
            tiltGlobeCamera(cam, p);
            for (const r of [R * 0.1 + 100, R * 1.5, R * 3.9, R * 4]) {
                cam.radius = r;
                expect(cam.pitch).toBeCloseTo(p, 9);
                expect(tiltFromLook(cam)).toBeCloseTo(p, 6);
            }
        }
    });
});
